def rope(x,pos,theta):
    inv=theta**(-np.arange(0,256,2)/256.0); ang=pos*inv
    c=np.concatenate([np.cos(ang)]*2); s=np.concatenate([np.sin(ang)]*2)
    rot=np.concatenate([-x[...,128:],x[...,:128]],-1)
    return x*c+rot*s
